function check(input, actual, expected) {
  const [n] = input;
  if (!Array.isArray(actual) || actual.length !== 25 * n) return false;
  const holder = [-1, -1, -1, -1, -1], meals = [0, 0, 0, 0, 0];
  for (const entry of actual) {
    if (!Array.isArray(entry) || entry.length !== 3) return false;
    const [p, fork, action] = entry;
    if (![0, 1, 2, 3, 4].includes(p)) return false;
    const left = (p + 1) % 5, right = p;
    if (action === 3) {
      if (fork !== 0 || holder[left] !== p || holder[right] !== p) return false;
      meals[p] += 1;
    } else if ((action === 1 || action === 2) && (fork === 1 || fork === 2)) {
      const id = fork === 1 ? left : right;
      if (holder[id] !== (action === 1 ? -1 : p)) return false;
      holder[id] = action === 1 ? p : -1;
    } else return false;
  }
  return meals.every((count) => count === n) && holder.every((id) => id === -1);
}

