function validate(input) {
  const [n, starts, meal] = input;
  if (!Number.isInteger(n) || n < 1 || n > 60) return 'n must be an integer from 1 to 60.';
  if (starts.length !== 5) return 'starts needs 5 start times, one per philosopher.';
  if (!starts.every((t) => Number.isInteger(t) && t >= 0 && t <= 1000)) return 'Each start time is an integer from 0 to 1000 ms.';
  if (!Number.isInteger(meal) || meal < 1 || meal > 100) return 'meal must be an integer from 1 to 100 ms.';
  return null;
}

