function adapt(input, solve, kit) {
  const [n, starts, meal] = input, log = [];
  const table = new solve();
  if (!table || typeof table.wantsToEat !== 'function') throw new Error('DiningPhilosophers needs a method wantsToEat.');
  const holder = [-1, -1, -1, -1, -1], eating = [false, false, false, false, false], sides = ['', 'left', 'right'];
  const deadline = Math.max(...starts) + 5 * n * (meal + 10) + 1000;
  let finished = 0;
  return new Promise((resolve, reject) => {
    const fail = (message) => reject(new Error(message));
    // One call of wantsToEat: callbacks that check the rules and log every action.
    const call = (p, used) => {
      const forks = [-1, (p + 1) % 5, p];
      const once = (name) => {
        if (used.has(name)) fail(`Philosopher ${p} called ${name} twice in one call.`);
        used.add(name);
      };
      const pick = (side) => () => {
        once(side === 1 ? 'pickLeftFork' : 'pickRightFork');
        const fork = forks[side];
        if (holder[fork] !== -1) fail(`Philosopher ${p} picks up fork ${fork} while philosopher ${holder[fork]} holds it.`);
        holder[fork] = p;
        log.push([p, side, 1]);
        kit.trace(`Philosopher ${p} picks up the ${sides[side]} fork (fork ${fork})`);
      };
      const put = (side) => () => {
        once(side === 1 ? 'putLeftFork' : 'putRightFork');
        const fork = forks[side];
        if (holder[fork] !== p) fail(`Philosopher ${p} puts down fork ${fork} without holding it.`);
        else if (eating[p]) fail(`Philosopher ${p} puts down fork ${fork} before the meal is over; await eat() first.`);
        holder[fork] = -1;
        log.push([p, side, 2]);
        kit.trace(`Philosopher ${p} puts down the ${sides[side]} fork (fork ${fork})`);
      };
      const eat = () => {
        once('eat');
        if (holder[forks[1]] !== p || holder[forks[2]] !== p) fail(`Philosopher ${p} eats without holding both forks.`);
        eating[p] = true;
        log.push([p, 0, 3]);
        kit.trace(`Philosopher ${p} starts eating`);
        return new Promise((done) => setTimeout(() => {
          eating[p] = false;
          kit.trace(`Philosopher ${p} finishes eating`);
          done();
        }, meal));
      };
      return table.wantsToEat(p, pick(1), pick(2), eat, put(1), put(2));
    };
    const run = async (p) => {
      for (let k = 1; k <= n; k++) {
        kit.trace(`Philosopher ${p} is hungry (meal ${k} of ${n})`);
        const used = new Set();
        await call(p, used);
        if (used.size !== 5) fail(`Philosopher ${p}'s call returned before picking up both forks, eating and putting both down.`);
      }
      finished += 1;
      if (finished === 5) resolve(log);
    };
    // Philosophers with the same start time begin in one go, in index order.
    const groups = new Map();
    starts.forEach((t, p) => groups.set(t, [...(groups.get(t) || []), p]));
    for (const [t, group] of groups) {
      setTimeout(() => {
        for (const p of group) run(p).catch((error) => fail(`wantsToEat failed for philosopher ${p}: ${error && error.message || error}`));
      }, t);
    }
    setTimeout(() => fail(`After ${deadline} ms, ${5 - finished} philosophers have not finished their meals: is there a deadlock?`), deadline);
  });
}

