class DiningPhilosophers {
  constructor() {
    this.taken = [false, false, false, false, false];
    this.waiting = [[], [], [], [], []];
  }

  acquire(fork) {
    if (!this.taken[fork]) {
      this.taken[fork] = true;
      return Promise.resolve();
    }
    return new Promise((resolve) => this.waiting[fork].push(resolve));
  }

  release(fork) {
    const next = this.waiting[fork].shift();
    if (next) next();
    else this.taken[fork] = false;
  }

  async wantsToEat(philosopher, pickLeftFork, pickRightFork, eat, putLeftFork, putRightFork) {
    const right = philosopher;
    const left = (philosopher + 1) % 5;
    await this.acquire(Math.min(left, right));
    await this.acquire(Math.max(left, right));
    pickLeftFork();
    pickRightFork();
    await eat();
    putLeftFork();
    putRightFork();
    this.release(left);
    this.release(right);
  }
}

