class DiningPhilosophers {
  constructor() {
    this.busy = false;
    this.queue = [];
  }

  // One philosopher at a time: slow, but nobody ever reaches for a fork in use.
  async wantsToEat(philosopher, pickLeftFork, pickRightFork, eat, putLeftFork, putRightFork) {
    if (this.busy) await new Promise((resolve) => this.queue.push(resolve));
    this.busy = true;
    pickRightFork();
    pickLeftFork();
    await eat();
    putRightFork();
    putLeftFork();
    const next = this.queue.shift();
    if (next) next();
    else this.busy = false;
  }
}

