function generate(rand, size) {
  const small = size === 'small';
  const n = small ? 1 + Math.floor(rand() * 4) : 50 + Math.floor(rand() * 11);
  const top = small ? 20 : 300, roll = rand();
  const starts = Array.from({ length: 5 }, () => (roll < 0.35 ? 0 : Math.floor(rand() * (top + 1))));
  const meal = 1 + Math.floor(rand() * (small ? 5 : 20));
  return [n, starts, meal];
}
